  { n: 71, stage: 'xryso', themeEl: 'Αντιμετώπιση Εκτάκτων Αναγκών', textEl: 'Να δείξεις τις Βασικές αρχές Πυρόσβεσης σύμφωνα με τα καιόμενα υλικά, στα μέλη της Ενωμοτίας σου και να και τους εξηγήσεις τους κύριους τύπους πυροσβεστήρων.', meansEl: 'Διανυκτέρευση στο Σύστημα', level: '1' },
  { n: 72, stage: 'xryso', themeEl: 'Προσκοπικές Δεξιότητες', textEl: 'Να οργανώσεις την ενωμοτία σου για την ετοιμασία μεγάλης κατασκευής για την οποία: · Να ετοιμάσεις σχέδιο και κατάλογο με τα υλικά · Να αιτιολογήσεις την χρήση των σχοινιών που προτίθεσαι να χρησιμοποιήσεις · Να αναθέσεις στα υπόλοιπα μέλη της Ενωμοτίας σου τις ευθύνες που θα έχουν κατά την ετοιμασία, την ανάρτηση, την στήριξη αλλά και αποσυναρμολόγηση της κατασκευής. · Να ετοιμάσεις τις κατάλληλες αγκυρώσεις σύμφωνα με τον τύπο του εδάφους.', meansEl: 'Ενωμοτιακή Δράση', level: '2' },
  { n: 73, stage: 'xryso', themeEl: 'Προσκοπικές Δεξιότητες', textEl: 'Να κολυμπήσεις ελεύθερα σε απόσταση 50μ και να δείξεις ότι γνωρίζεις τους κανόνες ασφάλειας στη Θάλασσα', meansEl: 'Προσωπική Ενασχόληση', level: '1' },
  { n: 74, stage: 'xryso', themeEl: 'Προσκοπικές Δεξιότητες', textEl: 'Να επιδείξεις ότι μπορείς να υπολογίσεις το ύψος μιας κατασκευής και την απόσταση που σας χωρίζει, κάνοντας χρήση μιας αποδεκτής μεθόδου υπολογισμού.', meansEl: 'Προσωπική Ενασχόληση Προσωπική Ενασχόληση', level: '1' },
  { n: 75, stage: 'xryso', themeEl: 'Προσκοπισμός και Κοινωνία', textEl: 'Να Αναγνωρίσεις την αξία της ειρηνικής συνύπαρξης των Λαών και να εξηγήσεις πως ο προσκοπισμός συμβάλλει στον τομέα αυτό', meansEl: 'Πρ. Ενασχόληση', level: '2' },
  { n: 76, stage: 'xryso', themeEl: 'Προσκοπισμός και Κοινωνία', textEl: 'Να Οργανώσεις με την Ενωμοτία σου δράση Κοινωνικής Προσφοράς στην περιοχή σου στα πλαίσια της Ημέρας Σκέψεως και να προβάλεις την σημασία της ημέρας για την Παγκόσμια Προσκοπική Κίνηση', meansEl: 'Ενωμοτιακή Δράση', level: '2' },
  { n: 77, stage: 'xryso', themeEl: 'Προσκοπισμός και Κοινωνία', textEl: 'Να Συμμετέχεις στο JOTA ή JOTI και να επικοινωνήσεις με Προσκόπους άλλων χωρών', meansEl: 'Ενωμοτιακή Δράση', level: '2' },
  { n: 78, stage: 'xryso', themeEl: 'Προσκοπισμός και Κοινωνία', textEl: 'Να Περιγράψεις τις βασικές Δομές και λειτουργίες της Ευρωπαϊκής Ένωσης και να εξηγήσεις τον τρόπο λήψης αποφάσεων', meansEl: 'Ενωμοτιακή Δράση', level: '3' },
  { n: 79, stage: 'xryso', themeEl: 'Προσκοπισμός και Κοινωνία', textEl: 'Να συμμετέχεις ενεργά στο Έπαθλο Προσκοπικής Εξερεύνησης η κάτι αντίστοιχο', meansEl: 'Ενωμοτιακή Άμιλα', level: '2' },
  { n: 80, stage: 'xryso', themeEl: 'Δράση και Επιβίωση στο ύπαιθρο', textEl: 'Να υποβάλεις κατάλογο εφοδίων και τροφίμων που θα χρειαστείς για διήμερη Δράση/διανυκτέρευση.', meansEl: 'Δράση Υπαίθρου', level: '1' },
  { n: 81, stage: 'xryso', themeEl: 'Δράση και Επιβίωση στο ύπαιθρο', textEl: 'Να ετοιμάσεις καταφύγιο στο ύπαιθρο με απλά φυσικά ή ανανεώσιμα υλικά όπου θα ετοιμάσεις δείπνο και θα διανυκτερεύσεις. Να πάρεις μαζί σου μόνο 12 προσωπικά είδη και να δικαιολογήσεις στον Αρχηγό τις επιλογές σου', meansEl: 'Δράση Υπαίθρου', level: '1' },
  { n: 82, stage: 'xryso', themeEl: 'Δράση και Επιβίωση στο ύπαιθρο', textEl: 'Να επιδείξεις τις προφυλάξεις που θα πρέπει να πάρεις κατά την διαβίωση αυτή, και να απαριθμήσεις τους πιθανούς κυνδύνους που δυνατόν να αντιμετωπίσεις.', meansEl: 'Δράση Υπαίθρου', level: '1' },
  { n: 83, stage: 'xryso', themeEl: 'Δράση και Επιβίωση στο ύπαιθρο', textEl: 'Μία(1) Διανυκτέρευση στο', meansEl: 'Δράση Υπαίθρου', level: '2' },
  { n: 84, stage: 'xryso', themeEl: 'Δράση και Επιβίωση στο ύπαιθρο', textEl: 'Δύο (2) Ενωμοτιακές', meansEl: 'Δράση Υπαίθρου', level: '2' },
  { n: 85, stage: 'xryso', themeEl: 'Συμμετοχή', textEl: 'Μία (1) Θερινή Κατασκήνωση διάρκειας τουλάχιστον Επτά (7) ημερών', meansEl: 'Δράση Υπαίθρου', level: '2' },
  { n: 86, stage: 'xryso', themeEl: 'Συμμετοχή', textEl: 'Ενεργό συμμετοχή στην Ομάδα για περίοδο εννέα (9) μηνών (από την ονομασία σου ως Πρόσκοπος Αργυρού Τρίφυλλου)', meansEl: 'Δράση Υπαίθρου', level: '2' },
  { n: 87, stage: 'xryso', themeEl: 'Προσωπική Ανασκόπηση και Ολοκλήρωση', textEl: 'Να παρουσιάσεις στην Ομάδα οπτικοακουστικό Υλικό από την ζωή σου στην Ομάδα στην παρουσία του Αρχηγού. Στα πλαίσια αυτή της παρουσίασης να ετοιμάσεις μια καλλιτεχνική αναφορά ή κατασκευή με βάση τις Θεματικές Ενότητες και να εξηγήσεις το σκεπτικό των επιλογών σου', meansEl: 'Προσωπική Συνέντευξη', level: '2, 3' },
  { n: 88, stage: 'xryso', themeEl: 'Προσωπική Ανασκόπηση και Ολοκλήρωση', textEl: 'Να συζητήσεις με τον Αρχηγό σου τις εμπειρίες που απόκτησες στην Ομάδα και να αναφέρεις σε αυτόν: · Την πιο ευχάριστη σου εμπειρία · Την πιο δύσκολη δράση που συμμετείχες · Αυτή που σου άφησε τις πιο μεγάλες εντυπώσεις', meansEl: 'Προσωπική Συνέντευξη', level: '3' },
  { n: 89, stage: 'xryso', themeEl: 'Προσωπική Ανασκόπηση και Ολοκλήρωση', textEl: 'Να συμμετάσχεις σε δράση της Κοινότητας Ανιχνευτών', meansEl: 'Δράση', level: '1' },
  { n: 90, stage: 'xryso', themeEl: 'ΔΟΚΙΜΑΣΙΑ', textEl: 'Να συμμετάσχεις σε δράση της Τ.Ε. ή της Ε.Ε. διάρκειας Δύο (2) ημερών στην οποία θα κληθείς να πραγματοποιήσεις: Α. Πορεία από 10 μέχρι 15χλμ. σε άγνωστο έδαφος ή ανάλογο ταξίδι δια θαλάσσης (για Ν/Π). Β. Ταχύ Οδοιπορικό και χαρτογράφηση πορείας για απόσταση 1 χλμ η χάραξη πορείας πλεύσης (για Ν/Π). Γ. Ημερολόγιο Πορείας. Δ. Μαγείρεμα χωρίς τη χρήση μαγειρικών σκευών. Κατά της διάρκεια της πορείας θα κληθείς να συμμετάσχεις σε επεισόδια Ετοιμότητας ή άλλες Προσκοπικές Δοκιμασίες. Να προσφέρεις τις υπηρεσίες σου σε μια από τις Κοινότητες της περιοχής της Πορείας.', meansEl: 'Ζωή Υπαίθρου', level: '4' },
  { n: 91, stage: 'xryso', themeEl: 'ΑΠΟΝΟΜΗ', textEl: 'Από τον Τοπικό ή Επαρχιακό Έφορο', meansEl: '', level: '4' }
