export const BADGES: Array<{ slug: string, titleEl: string, category: string, emoji: string, requirementsEl: string[] }> = [
  { slug: 'athliti', titleEl: 'Αθλητή', category: 'drasis', emoji: '🏃', requirementsEl: ['Ασχολούμαι συστηματικά με ένα ατομικό άθλημα πέραν των 2 ετών (π.χ. κλασσικός αθλητισμός, κολύμπι, ρυθμική γυμναστική, κλπ).', '— ή —', ':: Υλοποιώ τις ακόλουθες απαιτήσεις:', 'Συμμετέχω σε αθλητική δραστηριότητα, τουρνουά ή αθλητικό αγώνα στα πλαίσια μιας προσκοπικής δράσης.', 'Κάνω μια σύντομη παρουσίαση στην Ενωμοτία ή στην Ομάδα μου για τη σημασία της άθλησης, τις αρχές της ευγενούς άμιλλας και τους κινδύνους που διατρέχουν οι αθλητές από την αλόγιστη χρήση βλαβερών ουσιών χρησιμοποιώντας παραδείγματα από μεγάλα αθλητικά γεγονότα όπως π.χ. οι Ολυμπιακοί Αγώνες ή Παγκόσμια ή Ευρωπαϊκά Πρωταθλήματα.', 'Κάνω μια σύντομη παρουσίαση στην Ενωμοτία ή στην Ομάδα μου για ένα άθλημα που με ενδιαφέρει (κανονισμοί, κορυφαίοι αθλητές ή ομάδες και επιδόσεις σε τοπικό και διεθνές επίπεδο).', 'Αναγνωρίζω την προσπάθεια κάθε αθλητή και εκτιμώ την επίδοση του. Αντιλαμβάνομαι τους κινδύνους που διατρέχουν οι αθλητές από τραυματισμούς και την αλόγιστη χρήση βλαβερών ουσιών.'] },
  { slug: 'aliea', titleEl: 'Αλιέα', category: 'drasis', emoji: '🎣', requirementsEl: ['Γνωρίζω τους κανόνες ασφαλείας όταν ψαρεύω στη θάλασσα και σε υδατοφράκτες χρησιμοποιώντας πετονιά.', 'Γνωρίζω τους κανόνες του Τμήματος Αλιείας για το ψάρεμα στη θάλασσα και τους υδατοφράκτες.', 'Συμμετέχω σε έξι εξορμήσεις ψαρέματος στη θάλασσα ή σε υδατοφράκτες, κρατώντας ημερολόγιο για τα ψάρια που ψάρεψα (είδος, μέγεθος, δόλωμα κλπ) και το παρουσιάζω στην Ομάδα μου.', 'Γνωρίζω ποιους θα ειδοποιήσω αν παρατηρήσω ρύπανση στη θάλασσα ή στον υδατοφράκτη ή νεκρά ψάρια στην επιφάνεια του νερού.', 'Γνωρίζω και εξηγώ γιατί τα υδρόβια φυτά είναι σημαντικά στον κύκλο της ζωής.', 'Γνωρίζω να δένω αγκίστρι στην πετονιά και να ετοιμάζω καλάμι για ψάρεμα.', 'Αναγνωρίζω δύο ψάρια του γλυκού νερού που υπάρχουν στους Κυπριακούς υδατοφράκτες και έξι ψάρια της Κυπριακής θάλασσας που μπορώ να ψαρέψω με πετονιά.', 'Καθαρίζω ένα ψάρι που έχω ψαρέψει και το μαγειρεύω στα κάρβουνα ή στο φούρνο ή σε τηγάνι.'] },
  { slug: 'anarrichisis', titleEl: 'Αναρρίχησης', category: 'drasis', emoji: '🧗', requirementsEl: ['Με τη βοήθεια εκπαιδευτή, συμμετέχω σε δράση αναρρίχησης πάνω σε τοίχο αναρρίχησης με κατακόρυφη κλίση ή πάνω σε βράχο ύψους έξι μέτρων.', 'Με τη βοήθεια εκπαιδευτή συμμετέχω σε δράση αναρρίχησης πάνω σε σχοινί, σε ύψος τριών μέτρων.', 'Γνωρίζω τους κινδύνους που εμπεριέχονται στο άθλημα της αναρρίχησης και πώς να πάρω όλα τα προστατευτικά μέτρα για τον εαυτό μου και τους άλλους.', 'Γνωρίζω τα υλικά που χρησιμοποιούνται στις αναρριχήσεις καθώς επίσης και τους τρόπους συντήρησης και φύλαξής τους.', 'Γνωρίζω τους βασικούς κόμπους που χρησιμοποιούνται σε μία αναρριχητική δράση (π.χ. καντηλίτσα, διπλό οχταράκι) και ξέρω πότε και που τους χρησιμοποιώ.'] },
  { slug: 'archaiologias', titleEl: 'Αρχαιολογίας', category: 'drasis', emoji: '🏺', requirementsEl: ['Ετοιμάζω μια σύντομη αναφορά για μια περίοδο της Ιστορίας της Κύπρου (π.χ. Παλαιολιθική, Ελληνιστική, Μεσαιωνική κλπ).', 'Επισκέπτομαι και ξεναγώ την Ενωμοτία ή την Ομάδα μου σε έναν ιστορικό χώρο που σχετίζεται με την περίοδο που επέλεξα στην απαίτηση 1.', 'Ετοιμάζω μια σύντομη παρουσίαση για την Ομάδα μου, με οπτικοακουστικό υλικό, για την περίοδο που επέλεξα στην απαίτηση 1, εμπλουτίζοντάς την με φωτογραφίες από την επίσκεψή που πραγματοποιήσαμε σύμφωνα με την απαίτηση 2.'] },
  { slug: 'paratiriti', titleEl: 'Παρατηρητή', category: 'drasis', emoji: '🔭', requirementsEl: ['Συμμετέχω σε παιγνίδι «ΚΙΜ» στο οποίο αναγνωρίζω τουλάχιστον 24 από τα 30 αντικείμενα που παρουσιάζονται σε διάρκεια ενός λεπτού.', 'Ετοιμάζω αποτυπώματα ίχνους (αρνητικό και θετικό) με τη βοήθεια γύψου για 2 από τα πιο κάτω: ➢ Άγριου ζώου ➢ Πουλιού ➢ Ανθρώπου ➢ Τροχοφόρου', 'Βοηθώ στην ετοιμασία πορείας μήκους δύο χιλιομέτρων με ανιχνευτικά σημεία σε παιχνίδι της Ενωμοτίας ή της Ομάδας μου.', 'Ετοιμάζω μία καλλιτεχνική αναφορά με ανιχνευτικά σημεία.', 'Παρακολουθώ ένα επεισόδιο διάρκειας τουλάχιστον ενός λεπτού με τη συμμετοχή τριών ατόμων το οποίο και περιγράφω με λεπτομέρεια.', 'Παρακολουθώ χωρίς να γίνω αντιληπτός, τις κινήσεις ενός μέλους του Συστήματος μου τουλάχιστον δέκα λεπτών και τις περιγράφω.'] },
  { slug: 'podilasias', titleEl: 'Ποδηλασίας', category: 'drasis', emoji: '🚴', requirementsEl: ['Ασχολούμαι συστηματικά με το άθλημα της ποδηλασίας και είμαι μέλος ποδηλατικού ομίλου για περίοδο πέραν των δύο ετών.', '— ή —', ':: Υλοποιώ τις ακόλουθες απαιτήσεις:', 'Χρησιμοποιώ για περίοδο τουλάχιστον έξι μηνών με επιτυχία ποδήλατο.', 'Γνωρίζω πώς να διατηρώ το ποδήλατο μου σε καλή κατάσταση και να επιδιορθώνω μικρές ζημιές και φθορές, συμπεριλαμβανομένης και της επιδιόρθωσης ενός τρυπημένου ελαστικού.', 'Γνωρίζω τον κώδικα οδικής κυκλοφορίας και πως πρέπει να συμπεριφέρομαι στο δρόμο με το ποδήλατο μου.', 'Παίρνω όλα τα μέτρα ασφάλειας που απαιτούνται όπως κράνος, φωτισμό, φωσφορούχα αντανακλαστικά για το βράδυ κλπ.', 'Γνωρίζω να προσφέρω στον εαυτό μου ή σε άλλο άτομο τις πρώτες βοήθειες σε περίπτωση ατυχήματος με το ποδήλατο.', 'Συμμετέχω σε μια εξερεύνηση της Ομάδας Προσκόπων ή της Ενωμοτίας μου με ποδήλατα, απόστασης τουλάχιστον 10 χιλιομέτρων.'] },
  { slug: 'kolymviti', titleEl: 'Κολυμβητή', category: 'drasis', emoji: '🏊', requirementsEl: ['Ασχολούμαι συστηματικά με το άθλημα της κολύμβησης και είμαι μέλος Ναυτικού Ομίλου για περίοδο πέραν των 2 ετών.', '— ή —', ':: Υλοποιώ τις ακόλουθες απαιτήσεις:', 'Γνωρίζω τους κανονισμούς ασφάλειας των κολυμβητών και τα μέτρα προστασίας που απαιτούνται κατά την κολύμβηση σε ανοικτή θάλασσα και πισίνα.', 'Είμαι σε θέση να κολυμπήσω σε απόσταση 100 μέτρων ελεύθερο και ύπτιο και 50 μέτρα πρόσθιο ή πεταλούδα.', 'Μπορώ να καταδυθώ σε βάθος δύο μέτρων από την επιφάνεια της θάλασσας.', 'Γνωρίζω τα σήματα που χρησιμοποιούν οι ναυαγοσωστικοί σταθμοί στην παραλία για την προειδοποίηση των κινδύνων που υπάρχουν.', 'Μπορώ να κολυμπήσω σε απόσταση 30 μέτρων ελεύθερα, φορώντας μακρύ παντελόνι και φανέλα.', 'Γνωρίζω τους κινδύνους που υπάρχουν από την έκθεση του ατόμου στην ηλιακή ακτινοβολία και τα μέτρα προστασίας που πρέπει να λαμβάνονται, ιδιαίτερα τους καλοκαιρινούς μήνες, και ιδιαίτερα όταν βρίσκομαι στην παραλία.'] },
  { slug: 'diaviosis', titleEl: 'Διαβίωσης', category: 'drasis', emoji: '🏕️', requirementsEl: ['Γνωρίζω πως θα αντιμετωπίσω τις εξής περιπτώσεις: πυρετό, ηλίαση, αφυδάτωση, υποθερμία, λιποθυμία, ρινορραγία καθώς επίσης και πως να εφαρμόσω ΚΑΡΠΑ.', 'Γνωρίζω τους κινδύνους μετακίνησης ενός τραυματία και πως να χρησιμοποιήσω σήματα διάσωσης όπως σφυρίχτρα, φωτοβολίδες, το σήμα κινδύνου ΜΟΡΣ και σήματα εδάφους αέρος για να καθοδηγήσω μια ομάδα διάσωσης.', 'Γνωρίζω πως μπορώ να καθαρίσω ή να επεξεργαστώ ακάθαρτο νερό (καθαρισμός ή ετοιμασία αυτοσχέδιου μηχανισμού περισυλλογής βρόχινου νερού ή νερού από εξάτμιση – υγρασία).', 'Γνωρίζω τα είδη φωτιών και τα μέτρα ασφαλείας για άναμμα φωτιάς στην ύπαιθρο.', 'Γνωρίζω πως ανάβω φωτιά με τσακμακόπετρα, με τριβή ξύλων ή με οποιοδήποτε άλλο τρόπο χωρίς τη χρήση σπίρτων ή αναπτήρα.', 'Γνωρίζω τα μέρη και τη χρήση προσκοπικού σουγιά. ➢ Συμμετέχω με ομάδα τριών μέχρι επτά άλλων Προσκόπων σε δράση διαβίωσης (με πορεία συμπεριλαμβανομένης και νυκτερινής) διάρκειας 24-36 ωρών κατά την οποία: ➢ Να γίνει χρήση πυξίδας και χάρτη κατά την πορεία ➢ Να γίνει μαγείρεμα σε ανοικτή φωτιά χωρίς τη χρησιμοποίηση μαγειρικών σκευών εκτός από την ετοιμασία ροφημάτων. ➢ Να ετοιμαστεί καταφύγιο στο οποίο θα διανυκτερεύσουμε.', 'Εφαρμόζω μία μέθοδο προσανατολισμού χωρίς τη χρήση πυξίδας.'] },
  { slug: 'exereyniti', titleEl: 'Εξερευνητή', category: 'texnikis', emoji: '🧭', requirementsEl: ['Γνωρίζω να χρησιμοποιώ όργανα εξερεύνησης όπως την πυξίδα και το GPS (Global Positioning System).', 'Γνωρίζω τους κανονισμούς ασφαλείας κατά την διάρκεια μιας εξερεύνησης.', 'Γνωρίζω πως θα ενεργήσω σε περίπτωση ατυχήματος ή έκτακτου περιστατικού.', 'Γνωρίζω να επιλέγω, συσκευάζω τα απαραίτητα εφόδια για μία τριήμερη εξερεύνηση.', 'Συμμετέχω σε μία τριήμερη εξερεύνηση μαζί με τρεις άλλους Προσκόπους, κατά προτίμηση της Ενωμοτίας μου. (Η εξερεύνηση μπορεί να γίνει με πορεία, με ποδήλατα ή με σκάφος).', 'Κατά τη διάρκεια της εξερεύνησης μου: ➢ Να τηρηθεί ημερολόγιο. ➢ Να γίνει συλλογή από φύλλα ή/και πετρώματα που θα ανευρεθούν.'] },
  { slug: 'kataskinoti', titleEl: 'Κατασκηνωτή', category: 'texnikis', emoji: '⛺', requirementsEl: ['Κατασκηνώνω στο ύπαιθρο, μέσα σε αντίσκηνο ή ingloo με την Ενωμοτία και την Ομάδα μου για 8-12 ημέρες.', 'Συντονίζω το στήσιμο σκηνής 8 ατόμων. Εξηγώ το σωστό τρόπο που στήνεται η σκηνή και την ορθή φύλαξη της.', 'Συμμετέχω στο στήσιμο ατομικής σκηνής τύπου ingloo και γνωρίζω τον ορθό τρόπο φύλαξης και συντήρησης της σκηνής.', 'Επιλέγω τον καλύτερο χώρο σε μια περιοχή για την εγκατάσταση κατασκήνωσης Ενωμοτίας, λαμβάνοντας υπ\' όψη όλους τους σχετικούς παράγοντες που θα πρέπει να προσέξω.', 'Ετοιμάζω σχεδιάγραμμα του χώρου που επιλέγω για την κατασκήνωση τοποθετώντας σ’ αυτό όλες τις κατασκευές και ανέσεις που απαιτούνται για μια εβδομαδιαία κατασκήνωση Ενωμοτίας.', 'Συμμετέχω στην κατασκευή δύο τουλάχιστον μεγάλων κατασκευών ανέσεως κατασκήνωσης Ενωμοτίας (π.χ. τραπεζαρία, πύλη, κλπ).', 'Συμμετέχω στη συντήρηση του υλικού κατασκήνωσης και στη φύλαξη του μετά την ολοκλήρωση της καλοκαιρινής κατασκήνωσης.'] },
  { slug: 'kataskinotikis-technikis', titleEl: 'Κατασκηνωτικής Τεχνικής', category: 'texnikis', emoji: '🪢', requirementsEl: ['Έχω κατασκηνώσει για συνολική διάρκεια τουλάχιστον 12 ημερών σε τέσσερις διαφορετικούς κατασκηνωτικούς χώρους.', 'Αναλαμβάνω για τουλάχιστον τρεις μέρες, κατά τη διάρκεια κατασκήνωσης της Ομάδας Προσκόπων, τη φύλαξη και διατήρηση σε άριστη κατάσταση των υλικών της αποθήκης της κατασκήνωσης.', 'Αναλαμβάνω, για τουλάχιστον τρεις μέρες, κατά τη διάρκεια κατασκηνώσεων της Ομάδας Προσκόπων, υπεύθυνος υγιεινής της κατασκήνωσης φροντίζοντας για την καθαριότητα όλων των κοινόχρηστων χώρων και το πέταγμα των σκουπιδιών.', 'Κατά τη διάρκεια μιας κατασκήνωσης της Ομάδας Προσκόπων, αναλαμβάνω να εξηγήσω στα μέλη της Ομάδας τα πρακτικά μέτρα που πρέπει να προσέξουμε για να μην επηρεαστεί το φυσικό περιβάλλον και η άγρια ζωή στο χώρο της κατασκήνωσής μας.', 'Γνωρίζω πώς να χρησιμοποιώ με ασφάλεια και να συντηρώ ορθά τα προσκοπικά εργαλεία: πέλεκυ, πριόνι, αξίνα και σουγιά.', 'Ετοιμάζω για μια διήμερη δράση με διανυκτέρευση της Ενωμοτίας μου τα ακόλουθα: ➢ το πρόγραμμα ➢ το απαιτούμενο υλικό ➢ το μενού και τις ποσότητες τροφίμων που απαιτούνται ➢ το κοστολόγιο', 'Στο τέλος μιας διήμερης δράσης με διανυκτέρευση της Ενωμοτίας μου, ετοιμάζω μια σχετική αναφορά περίπου 200 λέξεων σχετικά με τη δράση.', 'Ετοιμάζω τη σκηνή φύλαξης των προμηθειών και τοποθετώ τα τρόφιμα και τις άλλες προμήθειες σε αυτή.'] },
  { slug: 'kataskinotikis-mageirikis', titleEl: 'Κατασκηνωτικής Μαγειρικής', category: 'texnikis', emoji: '🍲', requirementsEl: ['Ετοιμάζω το διαιτολόγιο για μια διήμερη δράση με διανυκτέρευση Ενωμοτίας.', 'Υπολογίζω τις ποσότητες και προμηθεύομαι όλα τα απαραίτητα υλικά με βάση το διαιτολόγιο που ετοίμασα στο (1) πιο πάνω.', 'Ετοιμάζω μαγειρείο κατασκήνωσης Ενωμοτίας.', 'Επιλέγω δύο από τις τρεις πιο κάτω απαιτήσεις: ➢ Μαγειρεύω και σερβίρω ένα γεύμα σε ανοικτή φωτιά κατασκήνωσης για μια Ενωμοτία χρησιμοποιώντας μαγειρικά σκεύη (π.χ. πιλάφι, κοκκινιστό κρέας ή κοτόπουλο). ➢ Μαγειρεύω για τον εαυτό μου και ακόμα ένα άτομο σε ανοικτή φωτιά κατασκήνωσης, σουβλάκι, αυγό στο πορτοκάλι ή τη ντομάτα, πατάτα ψητή, αυγό στη σούβλα και άζυμο άρτο (ψωμί), χωρίς τη χρήση μαγειρικών σκευών. ➢ Ετοιμάζω ένα φούρνο κατασκήνωσης με τη χρήση πήλινου ή άλλου αντικειμένου και μαγειρεύω σε αυτό ψητό κλέφτικο και πατάτες.', 'Γνωρίζω να παίρνω μέτρα προστασίας από τη φωτιά που χρησιμοποιώ για μαγείρεμα στο δάσος.', 'Γνωρίζω και παίρνω όλα τα αναγκαία μέτρα υγιεινής στο μαγειρείο της κατασκήνωσης.'] },
  { slug: 'skapanikis', titleEl: 'Σκαπανικής', category: 'texnikis', emoji: '🪵', requirementsEl: ['Γνωρίζω να δένω και να χρησιμοποιώ τους εξής κόμπους: σταυρόκομπο, ψαλιδιά, φίμωμα, καντηλίτσα, διπλή καντηλίτσα, σωστικό κόμπο, σφεντόνη, ψαρόκομπο, γάσσα ή ματισιά, φαναράκι, καρυδόκομπο.', 'Γνωρίζω να δένω και να χρησιμοποιώ τις εξής συνδέσεις: Σταυροειδή (παραδοσιακή και ιαπωνική), διαγώνιο, παράλληλη και τριπόδι.', 'Κατασκευάζω καλλιτεχνική αναφορά με τους κόμπους και τις συνδέσεις που αναφέρονται στην απαίτηση 1 και 2.', 'Γνωρίζω να κατασκευάζω και να χρησιμοποιώ το πλαίσιο γεφυροποιίας.', 'Γνωρίζω τις βασικές αρχές: ➢ Συντήρησης σχοινιών, σουγιά, πέλεκυ, πριονιού και αξίνας. ➢ Ακονίσματος σουγιά, πέλεκυ, πριονιού. ➢ Χρήσης σουγιά, πέλεκυ, πριονιού και αξίνας.', 'Γνωρίζω και εφαρμόζω τις βασικές αρχές ασφάλειας στη σκαπανική.', 'Γνωρίζω πως να κατασκευάζω και χρησιμοποιώ: τροχαλίες, εντατήρες και αγκυρώσεις (κανονική, ενταφιασμένη).', 'Συμμετέχω στην κατασκευή με επιτυχία δύο μεγάλων κατασκευών σκαπανικής παίρνοντας όλα τα απαραίτητα μέτρα προστασίας που απαιτούνται.'] },
  { slug: 'mageira', titleEl: 'Μάγειρα', category: 'texnikis', emoji: '🍳', requirementsEl: ['Ψωνίζω όλα όσα απαιτούνται για την ετοιμασία ενός γεύματος, που περιλαμβάνει πρώτο πιάτο (ορεκτικό), κύριο πιάτο και επιδόρπιο και επιδεικνύω γνώση της ισορροπημένης διατροφής.', 'Ετοιμάζω και σερβίρω, για τέσσερα άτομα, γεύμα που αποτελείται από πρώτο πιάτο (ορεκτικό), κύριο πιάτο και επιδόρπιο.', 'Ετοιμάζω μια συλλογή από πέντε διαφορετικά μενού που αντιπροσωπεύουν διάφορες κουλτούρες (π.χ. Γαλλικό, Κινέζικο, Ινδικό κλπ).', 'Μαγειρεύω ένα παραδοσιακό γλυκό (π.χ. σιάμαλι, χαλβά κλπ).', 'Μαγειρεύω ένα παραδοσιακό φαγητό (π.χ. σουβλάκια με σιεφταλιές, κεφτέδες κλπ).'] },
  { slug: 'pyroprostasias', titleEl: 'Πυροπροστασίας', category: 'texnikis', emoji: '🧯', requirementsEl: ['Επισκέπτομαι τον πλησιέστερο Πυροσβεστικό Σταθμό στην περιοχή μου και μαθαίνω τον τρόπο που λειτουργεί η Πυροσβεστική Υπηρεσία για την αντιμετώπιση φωτιάς.', 'Αντιλαμβάνομαι τον τρόπο που δημιουργείται και ενεργεί η καύση (φωτιά) και τον κίνδυνο και τα προβλήματα που δημιουργούνται από τον καπνό και την υπερθέρμανση.', 'Αναγνωρίζω τους κινδύνους και τις απαραίτητες προφυλάξεις που πρέπει να λαμβάνονται στο σπίτι σχετικά με: ➢ τις θερμάστρες (πετρελαίου, γκαζιού και ηλεκτρισμού) ➢ τις ηλεκτρικές οικιακές συσκευές ➢ το γκάζι και τη χρήση σπίρτων και αναπτήρα ➢ τη χρήση κεριών ➢ τη διακόσμηση δωματίου και τους κινδύνους για πρόληψη πυρκαγιάς.', 'Αντιλαμβάνομαι τη σημασία χρήσης ανιχνευτών καπνού (smoke detectors) στα κτίρια.', 'Αναγνωρίζω τους διάφορους τύπους πυροσβεστήρων και τη χρήση του καθενός.', 'Γνωρίζω πως θα αντιδράσω σε περίπτωση πυρκαγιάς: ➢ στο σπίτι ➢ στο σχολείο ➢ σε δημόσιο κτίριο ➢ σε αυτοκίνητο', 'Γνωρίζω τους κινδύνους που απειλούν τα δάση από τις φωτιές.', 'Λαμβάνω όλα τα μέτρα ασφάλειας όταν χρησιμοποιώ φωτιά στο δάσος.'] },
  { slug: 'topografoy', titleEl: 'Τοπογράφου', category: 'texnikis', emoji: '🗺️', requirementsEl: ['Γνωρίζω τα μέρη της πυξίδας.', 'Γνωρίζω δύο διαφορετικούς τρόπους προσανατολισμού χωρίς τη χρήση πυξίδας.', 'Μπορώ με τη χρήση πυξίδας να χαρτογραφήσω το χώρο της Εστίας του Συστήματός μου ή κάποιο άλλο χώρο που θα μου υποδειχθεί όπως π.χ. το χώρο της καλοκαιρινής κατασκήνωσης της Ομάδας μου.', 'Αναγνωρίζω και διαβάζω τα χαρακτηριστικά του γεωφυσικού χάρτη.', 'Αναγνωρίζω και κατανοώ τις ισοϋψείς καμπύλες.', 'Γνωρίζω τα βασικά τοπογραφικά σημεία και μπορώ να διαβάσω χάρτη.', 'Μπορώ να ακολουθήσω μια μικρή πορεία 2 χιλιομέτρων με αζιμούθια ή/και χρήση GPS.', 'Μπορώ να ετοιμάσω ταχύ οδοιπορικό για απόσταση 500 μέτρων και στη συνέχεια να χαρτογραφήσω την πορεία αυτή.', 'Μπορώ να μετρήσω με δύο διαφορετικές μεθόδους, χωρίς τη χρήση σύγχρονων μέσων μέτρησης, το καμπαναριό της εκκλησίας της ενορίας μου και ένα ακόμα ψηλό αντικείμενο που θα μου υποδειχθεί (π.χ. έναν ιστό ή ένα δέντρο) ή το πλάτος ενός ποταμού.'] },
  { slug: 'astronomoy', titleEl: 'Αστρονόμου', category: 'texnikis', emoji: '🌌', requirementsEl: ['Αποδεικνύω ότι έχω επαρκείς γνώσεις για τον κόσμο των αστεριών και πλανητών ως επίσης για τις κινήσεις τους.', 'Δείχνω και κατονομάζω: τη Μεγάλη και Μικρή Άρκτο, την Κασσιόπεια, τον Αρκτούρο και τον πολικό αστέρα.', 'Μπορώ να προσανατολίζομαι τη νύχτα, με τρόπο εκτός του πολικού αστέρα.', 'Ετοιμάζω μία παρουσίαση ή/και καλλιτεχνική αναφορά για το πλανητικό σύστημα.', 'Γνωρίζω τις κινήσεις και τις αιτίες των εκλείψεων.'] },
  { slug: 'meteorologoy', titleEl: 'Μετεωρολόγου', category: 'texnikis', emoji: '🌦️', requirementsEl: ['Τηρώ, για τουλάχιστο 15 μέρες, ημερολόγιο των ημερήσιων παρατηρήσεων μου σχετικά με: ➢ την ένταση και την κατεύθυνση του ανέμου ➢ τη νέφωση (τύποι νεφών και ποσότητα) ➢ τη θερμοκρασία ➢ την ατμοσφαιρική πίεση ➢ τη βροχόπτωση, χιονόπτωση, κλπ', 'Χρησιμοποιώ για τις μετρήσεις μου τα εξής όργανα μετεωρολογίας: ➢ θερμόμετρο ➢ βαρόμετρο ➢ ανεμόμετρο ➢ βροχόμετρο', 'Χρησιμοποιώ το διαδίκτυο για τη συλλογή και μελέτη μετεωρολογικών πληροφοριών μέσω χαρτών που ετοιμάζονται με τη βοήθεια δορυφόρων.', 'Ξεχωρίζω τους διάφορους τύπους νεφώσεων και τον τρόπο που σχηματίζονται.', 'Γνωρίζω πρακτικούς/παραδοσιακούς τρόπους πρόγνωσης του καιρού, που χρησιμοποιούνται στην περιοχή μου.', 'Κατασκευάζω και λειτουργώ μετεωρολογικό σταθμό.'] },
  { slug: 'episkeyasti', titleEl: 'Επισκευαστή', category: 'texnologias', emoji: '🔧', requirementsEl: ['Αναγνωρίζω και κατανοώ τα διάφορα σύμβολα που χρησιμοποιούνται για την ένδειξη κινδύνου σε διάφορα χημικά υλικά (π.χ. τοξικά, εύφλεκτα, κλπ) και παίρνω όλες τις απαραίτητες προφυλάξεις στη χρήση και την αποθήκευσή τους για να προστατεύσω τον εαυτό μου και τους άλλους.', 'Αναγνωρίζω και κατανοώ τους κινδύνους στο χώρο εργασίας, όπως για παράδειγμα τις γλιστερές επιφάνειες, τα φθαρμένα σύρματα και τον κίνδυνο ηλεκτροπληξίας κλπ.', 'Γνωρίζω να χρησιμοποιώ προστατευτικό εξοπλισμό όταν εργάζομαι, όπως γάντια, προστατευτικά γυαλιά, κράνος.', 'Γνωρίζω που βρίσκονται οι διακόπτες και η ασφάλεια του ηλεκτρικού ρεύματος και πώς να απενεργοποιήσω την παροχή ηλεκτρισμού σε περίπτωση ανάγκης.', 'Γνωρίζω τους περιορισμούς που υπάρχουν για την ερασιτεχνική απασχόληση στις επιδιορθώσεις και τις περιπτώσεις όπου πρέπει οι επιδιορθώσεις να γίνονται από ειδικούς.', 'Κάνω δύο από τις ακόλουθες εργασίες: ➢ Ξεβουλώνω νεροχύτη που έχει φράξει (μπλοκάρει). ➢ Επιδιορθώνω μια βρύση στην οποία υπάρχει διαρροή νερού (στάζει). ➢ Ρυθμίζω το φλοτέρ στο ντεπόζιτο νερού ή στο καζανάκι της τουαλέτας. ➢ Συνδέω μια ηλεκτρική πρίζα. ➢ Αλλάζω έναν καμένο λαμπτήρα.', 'Συμμετέχω σε μια μεγάλη εργασία επιδιόρθωσης (π.χ. μπογιατίζω το δωμάτιό μου ή την εστία της Ομάδας Προσκόπων, κλπ).'] },
  { slug: 'ilektronikoy', titleEl: 'Ηλεκτρονικού', category: 'texnologias', emoji: '💡', requirementsEl: ['Γνωρίζω και εφαρμόζω τα εξής: ➢ Τα πιο απλά ηλεκτρονικά εξαρτήματα και εξηγώ με απλά λόγια την αρχή λειτουργίας ηλεκτρονικών κυκλωμάτων. ➢ Αναγνωρίζω την τιμή με βάση τον κώδικα χρωμάτων στις αντιστάσεις και τους πυκνωτές και τη σημασία της τιμής ενός ηλεκτρονικού εξαρτήματος. ➢ Γνωρίζω τα σύμβολα που χρησιμοποιούνται στα ηλεκτρονικά κυκλώματα και πώς ξεχωρίζει η πολικότητα σε μία δίοδο και οι αριθμοί των επαφών σε ένα ολοκληρωμένο κύκλωμα.', 'Γνωρίζω τους κανόνες ασφαλείας που ακολουθούνται όταν χρησιμοποιούμε ευαίσθητα σε στατικό ηλεκτρισμό εξαρτήματα και πως κολλούμε αυτά σε πλακέτα ηλεκτρονικού κυκλώματος χρησιμοποιώντας κολλητήρι.', 'Μετρώ με τη βοήθεια πολυμέτρου και γνωρίζω τη σχέση που υπάρχει μεταξύ των πιο κάτω: ➢ Τάση ➢ Ένταση ρεύματος ➢ Αντίσταση', 'Εξηγώ τις βασικές διαφορές στη λειτουργία μεταξύ των ψηφιακών και αναλογικών κυκλωμάτων.', 'Γνωρίζω τα ηλεκτρονικά κυκλώματα εκτελώντας τα πιο κάτω: ➢ Κατασκευάζω τρία απλά ηλεκτρονικά κυκλώματα που βρίσκω από βιβλία ή περιοδικά ηλεκτρονικών ή σχεδιάζω ο ίδιος. Τουλάχιστον ένα από τα τρία κυκλώματα να είναι κολλημένο σε πλακέτα. ➢ Εξηγώ τις βασικές αρχές του κάθε κυκλώματος και τις τυπικές μετρήσεις τάσης και έντασης ρεύματος που μέτρησα.'] },
  { slug: 'pliroforikis', titleEl: 'Πληροφορικής', category: 'texnologias', emoji: '💻', requirementsEl: ['Γνωρίζω τα μέρη ενός τυπικού συστήματος ηλεκτρονικού υπολογιστή.', 'Χρησιμοποιώ ηλεκτρονικό υπολογιστή για να ετοιμάσω δύο από τα εξής: ➢ Εφημερίδα της Ενωμοτίας μου ➢ Πίνακα προόδου της Ομάδας μου ➢ Πίνακα εσόδων και εξόδων της Ενωμοτίας μου ➢ Χάρτη της περιοχής που κατοικώ με τα κύρια σημεία', 'Με τη βοήθεια του ηλεκτρονικού υπολογιστή ετοιμάζω μια αφίσα σχετική με εκδήλωση της Ενωμοτίας ή της Ομάδας μου.', 'Μέσω του διαδικτύου, γνωρίζω έναν Πρόσκοπο από άλλη πόλη ή χώρα και κρατώ συχνή επαφή μαζί του για περίοδο τουλάχιστον τεσσάρων μηνών.', 'Χρησιμοποιώ το διαδίκτυο για να ενημερώνομαι για προσκοπικές δραστηριότητες από την ιστοσελίδα του Σώματος Προσκόπων Κύπρου, του Γραφείου της Ευρωπαϊκής Προσκοπικής Περιφέρειας και του Παγκόσμιου Προσκοπικού Γραφείου.', 'Αντιλαμβάνομαι τη σοβαρότητα χρήσης πειρατικών προγραμμάτων και τις απαγορευτικές διατάξεις της σχετικής νομοθεσίας, καθώς επίσης και τους κινδύνους που υπάρχουν από τη μετάδοση στο διαδίκτυο.', 'Χρησιμοποιώ το διαδίκτυο και επισκέπτομαι την ιστοσελίδα τουλάχιστον τεσσάρων άλλων Προσκοπικών Ομάδων, δύο από τις οποίες βρίσκονται σε ξένη χώρα.', 'Γνωρίζω τα διάφορα μέσα κοινωνικής δικτύωσης και πώς να τα χρησιμοποιώ σωστά. Γνωρίζω τυχών συνέπειες από την κακή χρήση τους.', 'Παρακολουθώ σεμινάριο σχετικό με την ασφάλεια χρήσης διαδικτύου από έμπειρο επαγγελματία.', 'Γνωρίζω πώς να δημιουργήσω και να χρησιμοποιήσω ηλεκτρονικό ταχυδρομείο.'] },
  { slug: 'radioerasitechni', titleEl: 'Ραδιοερασιτέχνη', category: 'texnologias', emoji: '📻', requirementsEl: ['Γνωρίζω το διεθνές φωνητικό αλφάβητο, το αλφάβητο ΜΟΡΣ, τον κώδικα Q (βασικές γνώσεις), τους χαιρετισμούς και τις συντομογραφίες.', 'Χρησιμοποιώ το πρωτόκολλο επικοινωνίας, τον κώδικα συμπεριφοράς ραδιοερασιτεχνών και το πρόθεμα (prefix) των κρατών.', 'Γνωρίζω τα βασικά μέρη ενός απλού πομποδέκτη, τι είναι οι ζώνες συχνοτήτων (bana plans) και πώς συμπληρώνω ένα «βιβλίο επαφής».', 'Γνωρίζω πώς να εγκαταστήσω και να θέσω σε λειτουργία ένα σταθμό ασυρμάτου και τις βασικές αρχές ασφάλειας που πρέπει να πάρω σαν χειριστής σταθμού ασυρμάτων.', 'Γνωρίζω τι σημαίνει: διάδοση (ηλεκτρ. Κυμάτων) ακουστικότητα – ευκρίνεια, διεθνής ώρα (GMT), έξοδος ισχύος ασυρμάτου (output), τάση ηλεκτρικού φορτίου και πώς μετρώνται.', 'Αναγνωρίζω πέντε τύπους κεραιών και μπορώ να υπολογίσω το μήκος μιας κατακόρυφης ή δίπολης κεραίας και πως να την κατασκευάσω.'] },
  { slug: 'grammatea', titleEl: 'Γραμματέα', category: 'anaptyxis', emoji: '🗂️', requirementsEl: ['Δακτυλογραφώ σε (word processor) ηλεκτρονικό υπολογιστή, ένα κείμενο από τουλάχιστον 200 λέξεις χωρίς να υπάρχουν ορθογραφικά λάθη και το αναρτώ στην επίσημη σελίδα του Συστήματος μου, αν υπάρχει.', 'Ετοιμάζω την ημερήσια διάταξη (θεματολόγιο) και κρατώ τα πρακτικά μιας συνεδρίας (π.χ. συνεδρίας Ενωμοτίας, Συμβουλίου Τιμής κλπ).', 'Ετοιμάζω οικονομικό προϋπολογισμό για μια δράση της Ενωμοτίας μου.', 'Γράφω ένα μήνυμα ηλεκτρονικού ταχυδρομείου αποτελούμενο από 50 μέχρι 100 λέξεις.', 'Ετοιμάζω και εκτυπώνω στον ηλεκτρονικό υπολογιστή µια πρόσκληση για µια εκδήλωση (π.χ. εκδήλωση της Ενωμοτίας, της Ομάδας κλπ).', 'Ετοιμάζω την έκθεση και τον απολογισμό για µια δράση (π.χ. δράση Ενωμοτίας, Ομάδας κλπ).'] },
  { slug: 'dimosiografoy', titleEl: 'Δημοσιογράφου', category: 'anaptyxis', emoji: '📰', requirementsEl: ['Ετοιμάζω για το Προσκοπικό Περιοδικό του Σ.Π.Κ. ή του Συστήματος ή της Ομάδας μου, μια ανταπόκριση που συνοδεύεται με φωτογραφικό υλικό.', 'Γνωρίζω πώς να συντάξω μια ανταπόκριση για ένα περιοδικό ή μια εφημερίδα και τα στοιχεία που αυτή θα πρέπει να συμπεριλαμβάνει.', 'Ετοιμάζω με τη χρήση ηλεκτρονικών μέσων (ήχου ή/και εικόνας) μια ανταπόκριση από μια δράση της Ενωμοτίας ή της Ομάδας μου.', 'Επισκέπτομαι τα γραφεία ενός μέσου μαζικής ενημέρωσης (π.χ. μιας εφημερίδας ή ενός περιοδικού ή του τμήματος ειδήσεων ενός σταθμού ραδιοφωνικού ή τηλεοπτικού).', 'Παίρνω συνέντευξη από ένα σημαντικό, για μένα, πρόσωπο την οποία παρουσιάζω στην Ομάδα μου ή δημοσιεύω στο περιοδικό του Συστήματός μου (αν υπάρχει).', 'Γνωρίζω τι σημαίνει δημοσιογραφική δεοντολογία και πώς θα πρέπει να συμπεριφέρεται ένας δημοσιογράφος στο πλαίσια της δημοσιογραφικής ηθικής.', 'Συμμετέχω για τουλάχιστον ένα χρόνο σε ομάδα ειδικού ενδιαφέροντος Δημοσιογραφίας, σχετικά με την συνεχή ενημέρωση της επίσημης σελίδας του Συστήματος, στην έκδοση εφημερίδας ή περιοδικού του Συστήματος ή της Ομάδας.'] },
  { slug: 'dimosion-scheseon', titleEl: 'Δημοσίων Σχέσεων', category: 'anaptyxis', emoji: '🤝', requirementsEl: ['Ετοιμάζω μία παρουσίαση ή ταινία μικρού μήκους σχετικά με τον προσκοπισμό και την παρουσιάζω σε μία εκδήλωση του Συστήματος μου.', 'Ετοιμάζω μια μικρή ανταπόκριση για το προσκοπικό περιοδικό σχετικά με μια δράση της Ενωμοτίας ή της Ομάδας μου.', 'Ηγούμαι μιας ομάδας από Προσκόπους στη διοργάνωση μιας δραστηριότητας για την προώθηση του Προσκοπισμού στην περιοχή του Συστήματός μου.', 'Ετοιμάζω ένα έντυπο (π.χ. εφημερίδα) το οποίο να περιέχει κείμενα και φωτογραφίες από τις δραστηριότητες της Ενωμοτίας μου κατά την τρέχουσα προσκοπική χρονιά.', 'Διευθετώ την επίσκεψη της Ενωμοτίας μου σε ένα ραδιοφωνικό ή τηλεοπτικό σταθμό ή μια εφημερίδα.', 'Διεξάγω μια έρευνα που περιέχει δέκα ερωτήσεις για την εικόνα του Προσκοπισμού στην περιοχή μου με τη συμπλήρωση, τουλάχιστον, είκοσι ερωτηματολογίων. Παρουσιάζω τα αποτελέσματα της έρευνας στο Συμβούλιο Τιμής της Ομάδας Προσκόπων.'] },
  { slug: 'metafrasti', titleEl: 'Μεταφραστή', category: 'anaptyxis', emoji: '🌍', requirementsEl: ['Συμμετέχω σε διάλογο διάρκειας τουλάχιστον δέκα λεπτών σε ξένη γλώσσα.', 'Ετοιμάζω μια σύντομη γραπτή αναφορά σε ξένη γλώσσα, τουλάχιστον 150 λέξεων, στην οποία περιγράφω μια δράση της Ενωμοτίας ή της Ομάδας μου.', 'Μεταφράζω μια παράγραφο από προσκοπικό περιοδικό ή εφημερίδα από ξένη γλώσσα στη γλώσσα μου.', 'Βοηθώ ως μεταφραστής στην παρουσίαση ενός θέματος διάρκειας τουλάχιστον 10 λεπτών.'] },
  { slug: 'syggrafea', titleEl: 'Συγγραφέα', category: 'anaptyxis', emoji: '✍️', requirementsEl: ['Ετοιμάζω ένα μικρό μυθιστόρημα και το παρουσιάζω στην Ομάδα μου.', 'Μελετώ ένα σημαντικό συγγραφέα και παρουσιάζω το συγγραφικό του έργο στην Ομάδα μου.', 'Γνωρίζω το κύριο συγγραφικό έργο τριών, τουλάχιστον συγγραφέων.'] },
  { slug: 'filathloy', titleEl: 'Φιλάθλου', category: 'anaptyxis', emoji: '🎽', requirementsEl: ['Παρακολουθώ τακτικά στο γήπεδο τους αγώνες της Ομάδας μου ή διοργανώσεις σχετικά με το άθλημα που με ενδιαφέρει, (π.χ. ποδοσφαίρου, πετόσφαιρας, καλαθόσφαιρας, αντισφαίρισης κλπ).', 'Γνωρίζω τους κανονισμούς του αθλήματος που μου αρέσει και τον τρόπο που εφαρμόζονται από το διαιτητή ή/και τους κριτές. Αναγνωρίζω την πίεση στην οποία βρίσκονται οι διαιτητές και οι κριτές όταν εξασκούν τα καθήκοντα τους και τα ανθρώπινα λάθη στα οποία μπορεί να υποπέσουν.', 'Χειροκροτώ τις προσπάθειες της ομάδας μου και εκτιμώ τις προσπάθειες των αντιπάλων.', 'Δεν παραφέρομαι στο γήπεδο και προσπαθώ πάντοτε να τηρώ κόσμια και αξιοπρεπή στάση.', 'Δεν παρασύρομαι από φανατισμό ή από τις ιδέες και απόψεις των άλλων αλλά έχω τη δική μου κρίση και άποψη. Αναγνωρίζω τους κανόνες του Fair Play και χειροκροτώ τους αθλητές που τους εφαρμόζουν.', 'Γνωρίζω τις μεγάλες αθλητικές προσωπικότητες στο άθλημα που μου αρέσει τόσο στην Κύπρο όσο και διεθνώς.', 'Γνωρίζω τις μεγάλες αθλητικές δραστηριότητες του αθλήματος που με ενδιαφέρει τόσο στην Κύπρο όσο και στο εξωτερικό, καθώς επίσης και τους Κύπριους πρωταγωνιστές.'] },
  { slug: 'fotografoy', titleEl: 'Φωτογράφου', category: 'anaptyxis', emoji: '📷', requirementsEl: ['Παρουσιάζω συλλογή από 24 φωτογραφίες μου, που σχετίζονται με θεματική ενότητα που έχω επιλέξει (π.χ. πορτρέτο, αθλητισμός, φύση, ζώα κλπ).', 'Γνωρίζω τις βασικές αρχές χρήσης φωτογραφικής μηχανής, τα βασικά μέρη της φωτογραφικής μηχανής και τη σημασία του φωτισμού στη λήψη φωτογραφιών.', 'Γνωρίζω πώς λειτουργούν οι ψηφιακές μηχανές και τον τρόπο με τον οποίο είναι δυνατόν να γίνει η επεξεργασία μιας φωτογραφίας σε ηλεκτρονικό υπολογιστή.', 'Γνωρίζω πώς μπορώ να εκτυπώσω μια φωτογραφία με τη βοήθεια ηλεκτρονικού υπολογιστή και εκτυπωτή και τι απαιτείται για όσο το δυνατό καλύτερα ποιοτικά αποτελέσματα.', 'Γνωρίζω ποια είναι η διαδικασία εμφάνισης ενός φωτογραφικού φιλμ, αφού επισκεφτώ και ενημερωθώ από έναν επαγγελματία φωτογράφο.', 'Αναλαμβάνω καθήκοντα φωτογράφου για την Ενωμοτία μου και παρουσιάζω συλλογή φωτογραφιών για μία περίοδο τουλάχιστον τριών μηνών.'] },
  { slug: 'energeiakis-oikonomias', titleEl: 'Ενεργειακής Οικονομίας', category: 'ypiresias', emoji: '🔌', requirementsEl: ['Δημιουργώ ένα κατάλογο από περιπτώσεις σπατάλης ενέργειας, που έχω παρατηρήσει κατά τη διάρκεια μιας εβδομάδας στο σπίτι μου, στο σχολείο μου και στο περιβάλλον που ζω.', 'Εισηγούμαι τρόπους εξοικονόμησης ενέργειας και προσπαθώ να τους εφαρμόσω στην καθημερινότητά μου.', 'Αναπτύσσω και παρουσιάζω στην Ομάδα 3 τρόπους εξοικονόμησης ενέργειας και τη σημασία της χρήσης ανανεώσιμων πηγών ενέργειας.', 'Οργανώνω Σύστημα Ανακύκλωσης στην Ομάδα μου ή στο Σύστημα και για διάρκεια τριών μηνών φροντίζω για την συλλογή και σωστή απόρριψη ανακυκλώσιμων υλικών.'] },
  { slug: 'koinotikis-anaptyxis', titleEl: 'Κοινοτικής Ανάπτυξης', category: 'ypiresias', emoji: '🏘️', requirementsEl: ['Αναγνωρίζω την έννοια και τη σημασία του εθελοντισμού στην κοινότητα και ειδικότερα της κοινότητάς μου.', 'Μελετώ τις ανάγκες της τοπικής μου κοινότητας και προτείνω δραστηριότητες κοινοτικής υπηρεσίας.', 'Επιλέγω 2 από τις δραστηριότητες κοινοτικής υπηρεσίας και τις εφαρμόζω με την Ενωμοτία μου ή την Ομάδα στην κοινότητα μου (με τη βοήθεια βαθμοφόρων).'] },
  { slug: 'xenagoy', titleEl: 'Ξεναγού', category: 'ypiresias', emoji: '🧳', requirementsEl: ['Γνωρίζω την περιοχή σε ακτίνα 2 χιλιομέτρων από το σπίτι μου ή το Σύστημα μου, και ετοιμάζω ένα δικό μου χάρτη στον οποίο τοποθετώ το σπίτι ή το Σύστημα μου, την εκκλησία της ενορίας, τα σχολεία, τα νοσοκομεία, τον αστυνομικό και πυροσβεστικό σταθμό και οποιαδήποτε άλλα σημαντικά κτίρια υπάρχουν.', 'Μπορώ να χρησιμοποιώ οδικό χάρτη ή GPS (Global Positioning System) ή Google map (στο χωριό και στην πόλη) για να βρω συγκεκριμένη διεύθυνση.', 'Χρησιμοποιώ το λεωφορείο για τη μετάβασή μου από το σπίτι στο κέντρο της πόλης.', 'Ετοιμάζω ένα δικό μου χάρτη με μουσεία και άλλα ιστορικά μέρη της πόλης ή της περιοχής μου, για να τα χρησιμοποιήσει ένας επισκέπτης στην πόλη ή στην περιοχή μου.', 'Ξεναγώ μία Ενωμοτία από άλλο Σύστημα στην πόλη ή την περιοχή μου.'] },
  { slug: 'pagkosmias-oikologias', titleEl: 'Παγκόσμιας Οικολογίας', category: 'ypiresias', emoji: '🌱', requirementsEl: ['Γνωρίζω τρία περιβαλλοντικά προβλήματα, πως επηρεάζουν τον πλανήτη μας και με ποιες ενέργειες μου, μπορώ να συμβάλω στη απάμβλυνση των προβλημάτων.', 'Γνωρίζω πέντε είδη ζωής (χλωρίδα, πανίδα, θαλάσσια είδη) που ευρίσκονται σε άμεσο κίνδυνο και τα μέτρα που λαμβάνονται για την προστασία τους.', 'Ετοιμάζω μια αφίσα με την οποία προσπαθώ να μεταφέρω το μήνυμα της ανάγκης για παγκόσμια οικολογική προστασία.', 'Γνωρίζω τον κύκλο του νερού και πως αυτός επηρεάζει το οικοσύστημα του πλανήτη.', 'Γνωρίζω τον κύκλο της ζωής και πως αυτός επηρεάζει το οικοσύστημα του πλανήτη.'] },
  { slug: 'politistikis-klironomias', titleEl: 'Πολιτιστικής Κληρονομιάς', category: 'ypiresias', emoji: '🏛️', requirementsEl: ['Συμμετέχω ενεργά σε ερασιτεχνική ομάδα που ασχολείται με την πολιτιστική κληρονομιά (π.χ. παραδοσιακούς χορούς, παραδοσιακή μουσική, παραδοσιακή τέχνη κλπ), για περίοδο τουλάχιστον έξι μηνών ή επισκέπτομαι 3 χώρους διατήρησης της πολιτιστικής κληρονομιάς (τεκμηρίωση με φωτογραφίες).', 'Έχω συμμετάσχει σε εκδήλωση όπου παρουσιάστηκε η πολιτιστική μας κληρονομιά (π.χ. χορευτική εκδήλωση, έκθεση κλπ).', 'Ετοιμάζω και παρουσιάζω στην Ομάδα μου, για δέκα λεπτά, ειδική παρουσίαση σχετική με την πολιτιστική μας κληρονομιά.'] },
  { slug: 'katanaloti', titleEl: 'Καταναλωτή', category: 'ypiresias', emoji: '🛒', requirementsEl: ['Γνωρίζω τα βασικά δικαιώματά μου ως καταναλωτής.', 'Γνωρίζω ποια είναι η τηλεφωνική γραμμή του Καταναλωτή και το σκοπό ύπαρξης και λειτουργίας της.', 'Γνωρίζω ποια τα βασικά πλεονεκτήματα και τους σημαντικότερους κινδύνους της αγοράς προϊόντων και υπηρεσιών από το διαδίκτυο.', 'Γνωρίζω τι είναι το barcode και το QR.', 'Γνωρίζω πως μπορώ να σαρώσω ένα κωδικό QR.', 'Παρουσιάζω στην Ενωμοτία μου ή στην Ομάδα μου ποιες είναι οι πιο σημαντικές πληροφορίες που πρέπει να αναγράφονται σε μια συσκευασία και την έννοια των ενδείξεων CE, ISO, HACCAP.', 'Γνωρίζω τους κίνδυνους των απομιμήσεων ή παραπλανητικών διαφημίσεων.', 'Παρουσιάζω έρευνα αγοράς για 5 ίδια υλικά ή τρόφιμα ή υπηρεσίες ή άλλο προϊόν από 5 διαφορετικές εταιρίες.'] },
  { slug: 'proton-voitheion', titleEl: 'Πρώτων Βοηθειών', category: 'ypiresias', emoji: '🩹', requirementsEl: [':: Επίπεδο 1 Το Πτυχίο Πρώτων Βοηθειών επιπέδου 1, απονέμεται στον Πρόσκοπο που θα εκπληρώσει τις ακόλουθες απαιτήσεις:', 'Γνωρίζω πως περιποιούμαι ένα απλό τραύμα.', 'Εξηγώ τι πρέπει να κάνω σε περίπτωση έκτακτης ανάγκης.', 'Γνωρίζω πώς περιποιούμαι τα ακόλουθα: σπάσιμο μύτης, εγκαύματα, ξένο σώμα στο μάτι.', 'Γνωρίζω τι πρέπει να κάνω στις περιπτώσεις: λιποθυμίας, θερμοπληξίας, καταπληξίας (σοκ), τροφικής δηλητηρίασης, τσιμπήματος από έντομο, δαγκώματος από ζώα, φίδια.', 'Ετοιμάζω το φαρμακείο της Ενωμοτίας μου και δικαιολογώ στα υπόλοιπα μέλη της Ενωμοτίας μου το περιεχόμενό του.', 'Επιδεικνύω πώς και που χρησιμοποιούμε τους τριγωνικούς και κυλινδρικούς επιδέσμους. Επίπεδο 2 Το Πτυχίο Πρώτων Βοηθειών επιπέδου 2, απονέμεται στον Πρόσκοπο που έχει παρακολουθήσει με επιτυχία πλήρη σειρά από μαθήματα Πρώτων Βοηθειών, της ηλικίας μέχρι 14 ετών και είναι κάτοχος του σχετικού πιστοποιητικού του Τάγματος Αγίου Ιωάννου ή οποιασδήποτε οργάνωσης παροχής εκπαίδευσης και σχετικής πιστοποίησης Πτυχίου Πρώτων Βοηθειών.'] },
  { slug: 'thriskeias', titleEl: 'Θρησκείας', category: 'ypiresias', emoji: '⛪', requirementsEl: ['Γνωρίζω το Σύμβολο της Πίστεως και την Κυριακή Προσευχή.', 'Γνωρίζω τι είναι η Αγία Γραφή και διηγούμαι κάποιο θαύμα ή παραβολή ή ομιλία του Χριστού.', 'Γνωρίζω λίγα λόγια για τον Άγιο του οποίου έχω το όνομα και αναφέρω που βρίσκεται η εκκλησία του.', 'Ετοιμάζω μία προσευχή και τη μοιράζομαι με την Ομάδα μου.', 'Προσφέρω τις υπηρεσίες μου σε διάφορες εκδηλώσεις της Εκκλησίας της ενορίας μου ή της πόλης ή του χωριού μου (π.χ. περιφορά Επιταφίου, τοπική πανήγυρης).', 'Επισκέπτομαι με την Ομάδα ή την Ενωμοτία μου, μία σημαντική Μονή ή Εκκλησία ή Εξωκλήσι της ενορίας ή της πόλης ή του χωριού μου και φροντίζω να ενημερωθώ για την ιστορία του.', 'Γνωρίζω τι είναι η ανεξιθρησκεία. Για Πρόσκοπους άλλης θρησκείας', 'Γνωρίζω τις βασικές αρχές της θρησκείας μου και ετοιμάζω μία παρουσίαση σχετικά.', 'Γνωρίζω το ιερό κείμενο ή βιβλίο της θρησκείας μου και τα σχετικά με τη διδασκαλία της.', 'Γνωρίζω τι είναι η ανεξιθρησκεία.', 'Γνωρίζω τα σημαντικότερα θρησκευτικά μνημεία της θρησκείας μου και ξεναγώ την Ενωμοτία μου σε ένα θρησκευτικό μνημείο που βρίσκεται κοντά στο Σύστημα μου.', 'Ετοιμάζω μία προσευχή και τη μοιράζομαι με την Ομάδα μου.'] },
  { slug: 'vivliofiloy', titleEl: 'Βιβλιόφιλου', category: 'psyxagogias', emoji: '📚', requirementsEl: ['Έχω διαβάσει κατά τα τελευταία δύο χρόνια, τουλάχιστον τέσσερα βιβλία.', 'Γνωρίζω πως να χρησιμοποιώ τις υπηρεσίες μιας βιβλιοθήκης και τον τρόπο με τον οποίο λειτουργούν οι κατάλογοι των βιβλιοθηκών (κατά τίτλο, συγγραφέα, εκδότη κλπ).', 'Χρησιμοποιώ το διαδίκτυο για την εξεύρεση ενός τίτλου βιβλίου ή σχετικά με το συγγραφικό έργο ενός συγγραφέα.', 'Χρησιμοποιώ εγκυκλοπαίδεια ή το διαδίκτυο, για εξεύρεση χρήσιμων πληροφοριών.', 'Γνωρίζω τα κυριότερα μέρη ενός βιβλίου.', 'Γνωρίζω τον τρόπο για σωστή αντιγραφή σύμφωνα με τα πνευματικά δικαιώματα.'] },
  { slug: 'zografoy', titleEl: 'Ζωγράφου', category: 'psyxagogias', emoji: '🎨', requirementsEl: ['Ζωγραφίζω μια σκηνή από κάποια ιστορία ή μυθιστόρημα που με συναρπάζει.', 'Ζωγραφίζω από το φυσικό (όπως το βλέπω) ένα αντικείμενο ή άτομο, προσπαθώντας να τηρήσω ορθές αναλογίες.', 'Ζωγραφίζω ένα τοπίο από το φυσικό, προσπαθώντας να αποδώσω τους χρωματισμούς και τα κύρια χαρακτηριστικά.', 'Ετοιμάζω συλλογή από έξι προσωπικούς πίνακες ή/και σχέδια ή/και σκίτσα που ζωγράφισα. Εξηγώ για τον καθένα τα στοιχεία που εκφράζονται και το λόγο που τα αποτύπωσα με τον τρόπο που ήθελα.', 'Αναφέρω στην Ενωμοτία μου, σε συντομία, την ιστορία ενός σημαντικού ζωγράφου. Σημείωση: Όλα τα πιο πάνω μπορούν να αποτυπωθούν ανάλογα, με τη χρήση ηλεκτρονικού υπολογιστή.'] },
  { slug: 'montelisti', titleEl: 'Μοντελιστή', category: 'psyxagogias', emoji: '🛩️', requirementsEl: ['Κατασκευάζω μοντέλο αεροπλάνου με μηχανή το οποίο και το πετώ πλοηγώ) με τη βοήθεια γραμμών (lines) ή remote control για τουλάχιστον 45 δευτερόλεπτα, ή/και Κατασκευάζω μοντέλο σκάφους, όχι μεγαλύτερο από 45 εκ., το οποίο μπορεί να ακολουθήσει, με τη μηχανή του, ευθεία κατεύθυνση τουλάχιστον 25 μέτρων, ή/και Κατασκευάζω μοντέλο αυτοκινήτου, με μηχανή το οποίο και το οδηγώ σε πίστα με στροφές για απόσταση τουλάχιστον 50 μέτρων.', 'Ετοιμάζω με υλικά που επιλέγω, το μοντέλο ενός κτιρίου, μιας περιοχής ή ενός αντικειμένου υπό κλίμακα.'] },
  { slug: 'moysikoy', titleEl: 'Μουσικού', category: 'psyxagogias', emoji: '🎵', requirementsEl: ['Ασχολούμαι συστηματικά με την εκμάθηση ενός μουσικού οργάνου για τουλάχιστον δύο χρόνια ή/και συμμετέχω σε ορχήστρα ή χορωδία.', '— ή —', ':: Υλοποιώ τις ακόλουθες απαιτήσεις:', 'Παρουσιάζω σε σόλο εκτέλεση με κάποιο μουσικό όργανο της αρεσκείας μου, δύο τραγούδια της δικής μου επιλογής στην Προσκοπική Πυρά της κατασκήνωσης ή μιας διήμερης δράσης της Ομάδας Προσκόπων.', 'Παρουσιάζω στην Ομάδα μου, έναν σημαντικό μουσικό και το έργο του, από το είδος της μουσικής που με ενδιαφέρει.', 'Ετοιμάζω με ανακυκλώσιμα ή άλλα φυσικά υλικά, ένα μουσικό όργανο και παρουσιάζω ένα ρυθμικό μοτίβο χρησιμοποιώντας το.', 'Γνωρίζω ποια είναι τα κυπριακά παραδοσιακά όργανα.', 'Παρουσιάζω τουλάχιστον τρία χαρακτηριστικά παραδοσιακά τραγούδια ή/και ποιήματα του τόπου μου.'] },
  { slug: 'pagkosmias-filias', titleEl: 'Παγκόσμιας Φιλίας', category: 'psyxagogias', emoji: '🕊️', requirementsEl: ['Συμμετέχω στην εκδήλωση JΟΤΑ ή JΟΤΙ και έρχομαι σε επαφή με Προσκόπους από άλλες χώρες.', 'Ανταλλάσσω προσκοπικά σήματα (μέσω αλληλογραφίας ή με προσωπική επαφή όπου αυτό είναι δυνατό) με Προσκόπους άλλων χωρών.', 'Αναγνωρίζω το Προσκοπικό Έμβλημα μιας χώρας από κάθε ήπειρο και τι συμβολίζει.', 'Γνωρίζω την ιστορία του Οργανισμού Ηνωμένων Εθνών και το ρόλο του στη διατήρηση της Παγκόσμιας Ειρήνης.', 'Αλληλογραφώ με ηλεκτρονικό ταχυδρομείο με Προσκόπους άλλων χωρών και μοιράζομαι μαζί τους τις εμπειρίες μου.', 'Αναγνωρίζω την αξία της ειρήνης και της ειρηνικής συμβίωσης μεταξύ των λαών. Γνωρίζω τις προσπάθειες για επίτευξη της Ολυμπιακής Εκεχειρίας.', 'Αποδέχομαι όλους τους συνανθρώπους μου, ανεξάρτητα από θρησκεία, φυλή ή εθνικότητα.'] },
  { slug: 'technon', titleEl: 'Τεχνών', category: 'psyxagogias', emoji: '🎭', requirementsEl: ['Συμμετέχω ενεργά σε οποιοδήποτε είδος τέχνης που με εμπνέει και με ενθουσιάζει για περίοδο τουλάχιστον έξι μηνών (π.χ. ζωγραφική, μουσική, γλυπτική, θέατρο, χορό, αρχιτεκτονική κλπ).', 'Περιγράφω με λεπτομέρεια δύο επισκέψεις μου στους χώρους έκφρασης της τέχνης (π.χ. θέατρο, γκαλερί κλπ) χρησιμοποιώντας φωτογραφικό υλικό, προγράμματα ή ταινίες σχετικά με το περιεχόμενο.', 'Είμαι σε θέση να αναφέρω την τρέχουσα πολιτιστική δραστηριότητα σχετικά με το είδος της τέχνης που μελετώ (π.χ. συναυλίες, θεατρικές παραστάσεις, εκθέσεις κλπ).', 'Μπορώ να συζητήσω τεχνικά θέματα της τέχνης που με ενδιαφέρει (π.χ. σύνθεση τραγουδιού, ρυθμούς ζωγραφικής, τεχνικές υποκριτικής κλπ).'] },
  { slug: 'cheirotechnias', titleEl: 'Χειροτεχνίας', category: 'psyxagogias', emoji: '🧶', requirementsEl: ['Κατασκευάζω ένα αντικείμενο από πηλό, δέρμα, σχοινί κλπ. Γνωρίζω πώς να χρησιμοποιώ με ασφάλεια όλα τα εργαλεία που χρειάζομαι (για την ετοιμασία του αντικειμένου απαιτείται τουλάχιστον χρόνος 3 ωρών).', 'Διακοσμώ ένα αντικείμενο με αρχαίες ή παραδοσιακές παραστάσεις.', 'Χρησιμοποιώ άχρηστα αντικείμενα και κατασκευάζω μια χρήσιμη κατασκευή (π.χ. φωτογραφοθήκη, μολυβοθήκη κλπ).', 'Επισκέπτομαι ένα εργαστήριο παραδοσιακής τέχνης/χειροτεχνίας και μελετώ ένα από το αντικείμενα που κατασκευάζονται σε αυτό.'] },
  { slug: 'psychagogias', titleEl: 'Ψυχαγωγίας', category: 'psyxagogias', emoji: '🎪', requirementsEl: ['Ετοιμάζω ένα σκετσάκι διάρκειας τουλάχιστον πέντε λεπτών και το παρουσιάζω μαζί με την Ενωμοτία μου σε μια Πυρά ή άλλη εκδήλωση της Ομάδας Προσκόπων ή της Ενωμοτία μου.', 'Ετοιμάζω και παρουσιάζω το πρόγραμμα μιας Προσκοπικής Πυράς.', 'Ηγούμαι ομάδας τριών Προσκόπων για την ετοιμασία και παρουσίαση μιας επετειακής εκδήλωσης χρησιμοποιώντας διάφορα μέσα όπως μουσική, ηλεκτρονικό υπολογιστή, χορό, δράμα κλπ),', '— ή —', ':: Διοργανώνω ένα πάρτι για τα μέλη της Ενωμοτίας μου.'] },
  { slug: 'evdomis-technis', titleEl: 'Έβδομης Τέχνης', category: 'psyxagogias', emoji: '🎬', requirementsEl: ['Γνωρίζω τα είδη κινηματογράφου και παρακολουθώ τουλάχιστον τα ακόλουθα: - Μία ανεξάρτητη ταινία μυθοπλασίας - Μία ταινία δημιουργικού ντοκιμαντέρ - Μία ταινία animation - Μία ταινία ευρωπαϊκού κινηματογράφου', 'Γνωρίζω τους σκηνοθετικούς κανόνες για σωστή φωτογραφία στον κινηματογράφο.', 'Γνωρίζω τους βασικούς χειρισμούς της κάμερας και το πρόγραμμα μονταρίσματος (movie maker /imovie).', 'Επισκέπτομαι στούντιο παραγωγής ή δημιουργίας animation.', 'Ετοιμάζω ταινία μυθοπλασίας ή ντοκιμαντέρ μικρού μήκους, μέχρι 5 λεπτά με θέμα της δικής μου επιλογής.'] },
  { slug: 'fysiodifi', titleEl: 'Φυσιοδίφη', category: 'eidikotitas', emoji: '🦋', requirementsEl: ['Για περίοδο δύο εποχών (π.χ. χειμώνα - άνοιξης) μελετώ τη ζωή ενός φυτού και ενός οργανισμού (ζώων, ερπετών, εντόμων κλπ) στην περιοχή που κατοικώ.', 'Εισηγούμαι τρόπους με τους οποίους μπορούν να μειωθούν οι αρνητικές επιπτώσεις από την ανθρώπινη δραστηριότητα.', 'Μελετώ τη φυσική ζωή που υπάρχει σε μια περιοχή ενός τετραγωνικού χιλιομέτρου στο ύπαιθρο. Καταγράφω τα φυτά και τους οργανισμούς που συνάντησα, καθώς επίσης και τη μορφολογία του εδάφους. Ετοιμάζω χάρτη της περιοχής και τοποθετώ σε αυτόν τα στοιχεία που έχω συλλέξει.', 'Επισκέπτομαι μια περιοχή στο ύπαιθρο, όπου υπάρχει ανθρώπινη επέμβαση, και καταγράφω τις επιπτώσεις της, δημιουργώντας σχετικό χάρτη.'] },
  { slug: 'ichnilati', titleEl: 'Ιχνηλάτη', category: 'eidikotitas', emoji: '🐾', requirementsEl: ['Επιδεικνύω τις ικανότητες του στην ιχνηλασία, τη χρησιμοποίηση του εδάφους, το καμουφλάζ, του ανέμου, των σκιών και στο πώς να καλύπτομαι εκτελώντας τα ακόλουθα κατά τη διάρκεια της ημέρας: ➢ Διέρχομαι 500 μέτρα ακάλυπτου εδάφους, πλησιάζοντας βαθμοφόρου που μου υποδείχθηκε, που βρίσκεται σε γνωστό σημείο. Παρακολουθώ χωρίς να γίνομαι αντιληπτός, για μισή ώρα και αναφέρω τις πράξεις του. ➢ Καμουφλάρομαι ανάλογα με το περιβάλλον και εάν είναι δυνατό κάτω από διαφορετικές συνθήκες.', 'Κατά τη διάρκεια της νύχτας: ➢ Πλησιάζω απαρατήρητος και χωρίς να ακουστώ, βαθμοφόρο που μου υποδείχθηκε, του οποίου η θέση είναι γνωστή. ➢ Διέρχομαι μεταξύ δύο βαθμοφόρων που βρίσκονται σ’ αρκετή απόσταση ο ένας από τον άλλο χωρίς να ξέρω τις θέσεις τους.', 'Αποδεικνύω ότι ιχνηλάτησα και μελέτησα τουλάχιστο τέσσερα άγρια πτηνά ή ζώα στη φυσική τους ζωή προσκομίζοντας σχεδιαγράμματα, φωτογραφίες τους και περιγραφή των αποτελεσμάτων των παρατηρήσεών μου.', 'Κατασκευάζω τρία αποτυπώματα από ίχνη ζώων.'] },
  { slug: 'perivallontos', titleEl: 'Περιβάλλοντος', category: 'eidikotitas', emoji: '♻️', requirementsEl: [':: Επιλέγω για να πραγματοποιήσω δύο τουλάχιστον από τα πιο κάτω:', 'Γνωρίζω τα κυριότερα ήδη ρύπανσης του περιβάλλοντος και εκθέτω απλούς τρόπους αντιμετώπισης.', 'Γνωρίζω πέντε απλούς τρόπους εξοικονόμησης νερού.', 'Ετοιμάζω ένα σκίτσο με τον ΚΥΚΛΟ ΤΗΣ ΖΩΗΣ.', 'Καταγράφω τη χλωρίδα και την πανίδα του τόπου που με ιδιαίτερη αναφορά σε όσα είδη κινδυνεύουν με εξαφάνιση.', 'Καταγράφω τις βασικότερες αιτίες πρόκλησης δασικών πυρκαγιών και τους τρόπους πρόληψης. Πραγματοποιώ υποχρεωτικά τα πιο κάτω:', 'Περπατώ σε ένα μονοπάτι της φύσης ή σε ένα πάρκο, καταγράφω πέντε φυτά που θα συναντήσω και γνωρίζω λίγα λόγια για το καθένα.', 'Συμμετέχω σε μια εκστρατεία καθαριότητας (π.χ. παραλιών) ή σε μια δεντροφύτευση.', 'Ετοιμάζω μια πρωτότυπη κατασκευή από ανακυκλώσιμα υλικά.', 'Ετοιμάζω μια φωλιά ή μια ταΐστρα για πουλιά.', 'Ετοιμάζω μια αφίσα με θέμα την προστασία του περιβάλλοντος.'] },
  { slug: 'agroti', titleEl: 'Αγρότη', category: 'eidikotitas', emoji: '🌾', requirementsEl: ['Επισκέπτομαι ένα από τα πιο κάτω, συμμετέχω στις εργασίες και παίρνω πληροφορίες για το επάγγελμα: - Γεωργική μονάδα - Κτηνοτροφική μονάδα - Πτηνοτροφική μονάδα - Μελισσοκομείο - Ιχθυοκαλλιέργεια - Μονάδας μεταποίησης αγροτικών προϊόντων', 'Γνωρίζω τον κύκλο εργασιών της μονάδας που επισκέφτηκα.', 'Ετοιμάζω μία παρουσίαση η οποία να περιλαμβάνει στοιχεία για τη μονάδα που επισκέφτηκα, όπως η φροντίδα, συγκομιδή και τα διάφορα προϊόντα που παράγονται, καθώς επίσης, και φωτογραφικό υλικό από την επίσκεψη μου.', 'Μπορώ να αναγνωρίσω τέσσερα γεωργικά μηχανήματα, γνωρίζω τη χρήση και την επικινδυνότητα τους.', 'Συλλέγω πληροφορίες για την παρασκευή ενός παραδοσιακού κυπριακού προϊόντος (π.χ. χαλούμι, σουτζούκο, χαρουπόμελο, κλπ)', 'Ενημερώνομαι για τις προφυλάξεις που πρέπει να πάρω (μέτρα προστασίας, σωστή ένδυση κλπ) προτού εισέλθω στη μονάδα που θα επισκεφτώ.', 'Γνωρίζω για τη χρήση φυτοφαρμάκων και άλλων ουσιών καθώς επίσης, γιατί η μη ορθή χρήση τους είναι επιβλαβής για τον οργανισμό.'] },
  { slug: 'dasonomoy', titleEl: 'Δασονόμου', category: 'eidikotitas', emoji: '🌲', requirementsEl: ['Αναγνωρίζω στις διάφορες εποχές του χρόνου τα εξής δασικά ενδημικά δέντρα: Πεύκος, Κυπαρίσσι, Ευκάλυπτος, Κέδρος, Έλατο, Πλάτανος, Λεύκη, Χαρουπιά, Ελιά.', 'Αναγνωρίζω στις διάφορες εποχές του χρόνου έξι θάμνους και αγριολούλουδα της Κύπρου.', 'Εξηγώ τον κύκλο της ζωής και τη σημασία του δάσους.', 'Εξηγώ τους κινδύνους που διατρέχει το δάσος από την πυρκαγιά, τα ζώα και τις ασθένειες.', 'Επισκέπτομαι ένα δασικό σταθμό και συζητώ με τους δασονόμους για την ενδυνάμωση της βλάστησης στα δάση, την αραίωση των δασών και την πυροπροστασία.', 'Γνωρίζω τις αρχές υλοτομίας, όπως το κόψιμο ενός δέντρου και τον κατατεμαχισμό του και τη χρησιμότητα των διαφόρων μερών του.', 'Κατά τη διάρκεια δράσης ή κατασκήνωσης εντοπίζω κάποια δασικά δέντρα ανάλογα με την περιοχή που είμαι, συλλέγω φύλλα και καρπούς και τα παρουσιάζω στην Ενωμοτία ή στην Ομάδα μου.'] }
]

